const cfg = $('Config').first().json;
const urls = String(cfg.trendFeeds || '').split(/[,\n]/).map((u) => u.trim()).filter((u) => /^https:\/\//i.test(u)).slice(0, 5);
if (!urls.length) return [{ json: { url: '' } }];
return urls.map((url) => ({ json: { url } }));

const cfg = $('Config').first().json;
const clean = (t) => String(t).replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/\s+/g, ' ').trim();

let ok = 0, failed = 0;
const trends = [];
for (const it of $input.all()) {
  const raw = it.json.data;
  if (typeof raw !== 'string' || !/<(rss|feed)[\s>]/i.test(raw)) { failed++; continue; }
  const titles = [...raw.matchAll(/<title[^>]*>([\s\S]*?)<\/title>/gi)].map((m) => clean(m[1]));
  const list = titles.slice(1).filter((t) => t.length > 3 && t.length < 200).slice(0, 8);
  if (list.length) { ok++; trends.push(...list); } else { failed++; }
}
const uniqueTrends = [...new Set(trends)].slice(0, 20);

const sd = $getWorkflowStaticData('global');
const recent = Array.isArray(sd.recentThemes) ? sd.recentThemes.slice(-20) : [];
const today = new Date().toISOString().slice(0, 10);

const aiInput =
  'TODAY: ' + today + '\n' +
  'BRAND: ' + cfg.brandName + '\n' +
  'NICHE: ' + cfg.niche + '\n' +
  'AUDIENCE: ' + cfg.audience + '\n' +
  'BRAND VOICE: ' + cfg.brandVoice + '\n' +
  'NUMBER OF HASHTAGS: ' + (Number(cfg.hashtagCount) || 10) + '\n\n' +
  'PUBLIC TREND SIGNALS (headlines from RSS feeds, for inspiration only, may be empty):\n' + (uniqueTrends.length ? uniqueTrends.map((t) => '- ' + t).join('\n') : '(none available today, use evergreen or seasonal ideas)') + '\n\n' +
  'RECENT THEMES ALREADY POSTED (do not repeat):\n' + (recent.length ? recent.map((t) => '- ' + t).join('\n') : '(none yet)');

return [{ json: { aiInput, trends: uniqueTrends, feedsOk: ok, feedsFailed: failed, recentThemes: recent } }];

const cfg = $('Config').first().json;
const sig = $('Collect Trend Signals').first().json;
const ai = $input.item.json.output || null;

const max = Math.min(30, Math.max(3, Number(cfg.hashtagCount) || 10));
const tags = ai && Array.isArray(ai.hashtags)
  ? [...new Set(ai.hashtags.map((h) => String(h).replace(/[^\p{L}\p{N}_]/gu, '')).filter(Boolean))].slice(0, max).map((h) => '#' + h)
  : [];

const ok = !!(ai && ai.imagePrompt && ai.caption && ai.theme);
let caption = '';
if (ok) {
  const tail = '\n\n' + (cfg.aiDisclosure ? cfg.aiDisclosure + '\n\n' : '') + tags.join(' ');
  let body = (ai.hook ? ai.hook.trim() + '\n\n' : '') + String(ai.caption).trim();
  const room = 2200 - tail.length;
  if (body.length > room) body = body.slice(0, Math.max(0, room - 1)).trim() + '…';
  caption = body + tail;
}
const flags = ai && ai.safetyFlags ? ai.safetyFlags : {};
const forceApproval = !!(flags.realPersonOrBrand || flags.sensitiveTopic);

return { json: {
  ok, theme: ok ? String(ai.theme) : '', trendAngle: ok ? String(ai.trendAngle || '') : '',
  caption, altText: ok ? String(ai.altText || '').slice(0, 1000) : '',
  imagePrompt: ok ? String(ai.imagePrompt).trim() + '. Style: ' + cfg.imageStyle + '. No text, no letters, no logos, no watermarks, no real people.' : '',
  forceApproval, feedsOk: sig.feedsOk, feedsFailed: sig.feedsFailed
} };

const p = $('Package Post').first().json;
const r = $input.item.json;
const out = Array.isArray(r.output) ? r.output[0] : r.output;
const ok = !r.error && r.status === 'succeeded' && typeof out === 'string' && /^https:\/\//i.test(out);
const detail = r.error ? (r.error.message || JSON.stringify(r.error)) : (r.detail || r.status || '');
return { json: Object.assign({}, p, { imageUrl: ok ? out : '', imageOk: ok, imageError: ok ? '' : String(detail).slice(0, 200) }) };

const p = $('Attach Image').first().json;
const cfg = $('Config').first().json;
let known = false, pass = false, issues = [];
const raw = $input.item.json.content;
if (typeof raw === 'string') {
  try {
    const m = raw.match(/\{[\s\S]*\}/);
    const q = JSON.parse(m[0]);
    known = typeof q.pass === 'boolean';
    pass = q.pass === true;
    issues = Array.isArray(q.issues) ? q.issues.slice(0, 5).map(String) : [];
  } catch (e) { /* quality result unreadable, a human will decide */ }
}
const auto = String(cfg.publishMode || '').toLowerCase() === 'auto' && known && pass && !p.forceApproval;
return { json: Object.assign({}, p, { qualityKnown: known, qualityPass: pass, qualityIssues: issues, autoPublish: auto }) };

const cfg = $('Config').first().json;
const p = $input.item.json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
let formUrl = '';
try { formUrl = $execution.resumeFormUrl || ''; } catch (e) { formUrl = ''; }
const hours = Number(cfg.approvalHours) || 12;

const notes = [];
if (!p.qualityKnown) notes.push('The AI quality check could not run, so please look at the image carefully.');
if (p.qualityKnown && !p.qualityPass) notes.push('AI quality check flagged: ' + (p.qualityIssues.join('; ') || 'see image'));
if (p.forceApproval) notes.push('The idea mentions a possible real person, brand or sensitive topic. Please double-check.');
if (String(cfg.publishMode).toLowerCase() === 'auto' && !p.autoPublish) notes.push('Auto-publish was skipped because a safety check did not pass.');

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:auto;border-radius:14px;overflow:hidden;border:1px solid #eee">' +
  '<div style="background:linear-gradient(135deg,#833ab4,#fd1d1d,#fcb045);color:#fff;padding:18px 22px"><div style="font-size:12px;letter-spacing:1px">DAILY CONTENT STUDIO</div><div style="font-size:22px;font-weight:bold">📸 Your post is ready for review</div></div>' +
  '<img src="' + esc(p.imageUrl) + '" alt="Preview" style="width:100%;display:block">' +
  '<div style="padding:18px 22px;font-size:14px;line-height:1.5;color:#222">' +
  '<p style="margin:0 0 6px"><b>Theme:</b> ' + esc(p.theme) + '</p>' +
  '<p style="white-space:pre-wrap;background:#fafafa;border-radius:8px;padding:12px;margin:0 0 12px">' + esc(p.caption) + '</p>' +
  (notes.length ? '<p style="color:#b3261e"><b>Heads up:</b> ' + esc(notes.join(' ')) + '</p>' : '') +
  (formUrl ? '<p style="text-align:center"><a href="' + esc(formUrl) + '" style="background:#833ab4;color:#fff;text-decoration:none;padding:12px 22px;border-radius:24px;display:inline-block;font-weight:bold">Review and decide</a></p>' : '<p>Open the waiting execution in n8n to approve.</p>') +
  '<p style="color:#777;font-size:12px">You can approve, reject, or edit the caption. If you do nothing within ' + hours + ' hours the post is skipped.</p></div></div>';

return { json: {
  ownerEmail: cfg.ownerEmail, emailSubject: '📸 Approve today\'s Instagram post: ' + p.theme, emailHtml,
  kind: 'approval', title: '📸 Instagram post ready for your approval', text: 'Theme: ' + p.theme + '\n' + (notes.length ? notes.join(' ') + '\n' : '') + 'Open the review form to approve, reject or edit.',
  link: formUrl, imageUrl: p.imageUrl
} };

const p = $('Quality Gate').first().json;
const j = $input.item.json;
const decision = String(j['Decision'] || '').toLowerCase();
return { json: Object.assign({}, p, {
  approved: decision.startsWith('approve'), timedOut: !decision,
  editedCaption: String(j['Edited caption (optional)'] || '').trim()
}) };

const cfg = $('Config').first().json;
const q = $('Quality Gate').first().json;
let caption = q.caption;
try {
  const d = $('Decision Gate').first().json;
  if (d && d.editedCaption) caption = d.editedCaption;
} catch (e) { /* auto-publish path, no human edit */ }
if (cfg.aiDisclosure && !caption.includes(cfg.aiDisclosure)) caption = caption + '\n\n' + cfg.aiDisclosure;
return { json: { caption: caption.slice(0, 2200), imageUrl: q.imageUrl, altText: q.altText, theme: q.theme } };

const cfg = $('Config').first().json;
const safe = (f, d) => { try { return f(); } catch (e) { return d; } };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const mask = (s) => String(s).replace(/Bearer\s+\S+/gi, 'Bearer ***').replace(/access_token=[^&"\s]+/gi, 'access_token=***').slice(0, 300);
const j = $input.item.json;
const prev = $prevNode.name;
const detail = mask(JSON.stringify(j.error || j.detail || j.message || {}));
const post = safe(() => $('Finalize Post').first().json, null) || safe(() => $('Attach Image').first().json, null) || {};
const theme = post.theme || safe(() => $('Package Post').first().json.theme, '') || '';
const imageUrl = post.imageUrl || '';

let kind = 'failure', title = '', text = '', link = '', color = '#d93025';
if (prev === 'Get Post Link') {
  kind = 'success'; color = '#188038';
  link = j.permalink || '';
  title = '✅ Instagram post published';
  text = 'Theme: ' + theme + (link ? '\nOpen: ' + link : '');
  const sd = $getWorkflowStaticData('global');
  sd.recentThemes = (Array.isArray(sd.recentThemes) ? sd.recentThemes : []).concat(theme).filter(Boolean).slice(-30);
} else if (prev === 'Approved?') {
  kind = 'skipped'; color = '#e8710a';
  title = '⏭️ Post skipped';
  text = (j.timedOut ? 'No decision was made in time.' : 'The post was rejected.') + ' Nothing was published. Theme: ' + theme;
} else if (prev === 'Idea Ready?') {
  title = '⚠️ No post today: idea step failed'; text = 'The AI did not return a usable post idea. It will try again at the next run.';
} else if (prev === 'Image OK?') {
  title = '⚠️ No post today: image step failed'; text = 'Image generation failed or timed out. ' + (j.imageError || '');
} else if (prev === 'Container Created?') {
  title = '⚠️ Instagram did not accept the post'; text = 'Check your access token, account ID and image URL. Details: ' + detail;
} else if (prev === 'Container Ready?') {
  title = '⚠️ Instagram is still processing the image'; text = 'Status: ' + (j.status_code || 'unknown') + '. Nothing was published. The container stays valid for 24 hours.';
} else {
  title = '⚠️ Publishing failed'; text = 'Instagram did not publish the post. Details: ' + detail;
}

const emailHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:520px;margin:auto;border-radius:12px;overflow:hidden;border:1px solid #eee">' +
  '<div style="background:' + color + ';color:#fff;padding:16px 20px;font-size:18px;font-weight:bold">' + esc(title) + '</div>' +
  (imageUrl ? '<img src="' + esc(imageUrl) + '" alt="" style="width:100%;display:block">' : '') +
  '<div style="padding:16px 20px;font-size:14px;line-height:1.5;color:#222;white-space:pre-wrap">' + esc(text) + '</div>' +
  (link ? '<p style="text-align:center;margin:0 0 18px"><a href="' + esc(link) + '" style="background:#833ab4;color:#fff;text-decoration:none;padding:10px 20px;border-radius:22px;display:inline-block">Open post</a></p>' : '') + '</div>';

return { json: { kind, title, text, link, imageUrl, ownerEmail: cfg.ownerEmail, emailSubject: title, emailHtml } };

const c = $('Config').first().json;
const out = [];
const https = (u) => typeof u === 'string' && /^https:\/\//i.test(u.trim());
for (const item of $input.all()) {
  const d = item.json;
  const plain = d.title + '\n' + d.text + (d.link && !d.text.includes(d.link) ? '\n' + d.link : '');
  if (c.telegramBotToken && c.telegramChatId) {
    const base = 'https://api.telegram.org/bot' + String(c.telegramBotToken).trim();
    if (d.imageUrl) out.push({ json: { channel: 'telegram', url: base + '/sendPhoto', body: { chat_id: String(c.telegramChatId).trim(), photo: d.imageUrl, caption: plain.slice(0, 1000) } } });
    else out.push({ json: { channel: 'telegram', url: base + '/sendMessage', body: { chat_id: String(c.telegramChatId).trim(), text: plain.slice(0, 4000) } } });
  }
  if (https(c.slackWebhookUrl) && /^https:\/\/hooks\.slack\.com\//i.test(c.slackWebhookUrl.trim())) {
    out.push({ json: { channel: 'slack', url: c.slackWebhookUrl.trim(), body: { text: '*' + d.title + '*\n' + d.text + (d.link && !d.text.includes(d.link) ? '\n<' + d.link + '|Open>' : '') } } });
  }
  if (https(c.teamsWebhookUrl)) {
    const body = [{ type: 'TextBlock', text: d.title, weight: 'Bolder', size: 'Medium', wrap: true }, { type: 'TextBlock', text: d.text, wrap: true }];
    if (d.imageUrl) body.push({ type: 'Image', url: d.imageUrl, size: 'Large' });
    const card = { '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4', body };
    if (d.link) card.actions = [{ type: 'Action.OpenUrl', title: 'Open', url: d.link }];
    out.push({ json: { channel: 'teams', url: c.teamsWebhookUrl.trim(), body: { type: 'message', attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: card }] } } });
  }
  if (https(c.webhookUrl)) {
    out.push({ json: { channel: 'webhook', url: c.webhookUrl.trim(), body: { event: 'instagram.content.' + d.kind, title: d.title, text: d.text, link: d.link, imageUrl: d.imageUrl, at: new Date().toISOString() } } });
  }
}
return out;
